#!/usr/bin/env python3
"""Composes artifact templates from layers: base, industry profile, stack profile, project-local.

A base template carries slot markers. A fragment fills slots. The composer is the only thing that
joins them, so the result is the same on every machine. Format and rules: docs/TEMPLATES.md.

  compose-templates.py --project DIR [--industry ID] [--stack ID] [--targets claude,copilot]
                       [--dry-run] [--force] [--json]
  compose-templates.py --project DIR --check     exit 1 when the composed files are stale
  compose-templates.py --lint                    check the framework's own templates and profiles
  compose-templates.py --list                    print the available industry and stack profiles

Standard library only. The framework root is the parent of this script's directory, so the same
file works from the plugin root, .claude/sdd-speckit/ and .specify/sdd-speckit/.
"""
import argparse
import hashlib
import itertools
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OVERRIDES = ".specify/templates/overrides"
LOCAL_FRAGMENTS = ".specify/templates/fragments"
CONFIG = ".specify/sdd-speckit.json"
NONE_IDS = {"industry": "none", "stack": "custom"}

SLOT_NAME = r"[a-z0-9]+(?:-[a-z0-9]+)*"
SLOT_RE = re.compile(r"^(?:<!-- slot:(%s)(:begin|:end)? -->|# slot:(%s)(:begin|:end)?)$" % (SLOT_NAME, SLOT_NAME))
FRAG_RE = re.compile(r"^(?:<!-- @slot (%s)( replace)? -->|# @slot (%s)( replace)?)$" % (SLOT_NAME, SLOT_NAME))
COMPOSED_RE = re.compile(r"sdd-speckit:composed industry=(\S+) stack=(\S+) inputs=([0-9a-f]+)")
BLOCK_BEGIN = "<!-- sdd-speckit:begin (generated by sdd-speckit-framework; edit outside this block) -->"
BLOCK_END = "<!-- sdd-speckit:end -->"
TIGHT_SUFFIXES = ("-rows", "-items")
FORBIDDEN_IN_FRAGMENTS = (re.compile(r"CLAUDE_PLUGIN_ROOT"), re.compile(r"/(?:sdd-speckit:)?speckit\.[a-z]"))
STACK_MAY_NOT_OVERLAY = ("spec-template.md",)
STACK_MAY_NOT_FILL = {"constitution-template.md": ("principles", "gates-rows")}


class ComposeError(Exception):
    pass


# ------------------------------------------------------------------ files

def read(path):
    with open(path, encoding="utf-8", newline="") as fh:
        return fh.read().replace("\r\n", "\n")


def read_json(path, fallback=None):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return fallback


def walk(base):
    """Relative posix paths of every file under base, sorted."""
    out = []
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames.sort()
        for name in sorted(filenames):
            if name == ".DS_Store":
                continue
            out.append(os.path.relpath(os.path.join(dirpath, name), base).replace(os.sep, "/"))
    return sorted(out)


# --------------------------------------------------------------- profiles

def profile_dir(root, kind, pid):
    return os.path.join(root, "profiles", "industries" if kind == "industry" else "stacks", pid)


def list_profiles(root, kind):
    base = os.path.join(root, "profiles", "industries" if kind == "industry" else "stacks")
    if not os.path.isdir(base):
        return []
    return sorted(d for d in os.listdir(base) if os.path.isfile(os.path.join(base, d, "profile.json")))


def load_profile(root, kind, pid):
    if not pid or pid == NONE_IDS[kind]:
        return None
    path = os.path.join(profile_dir(root, kind, pid), "profile.json")
    data = read_json(path)
    if data is None:
        raise ComposeError('%s profile "%s" was not found at %s' % (kind, pid, path))
    data.setdefault("id", pid)
    data["_dir"] = profile_dir(root, kind, pid)
    return data


# ------------------------------------------------- generated stack layer

DEFAULT_LABELS = {
    "language": "Language", "runtime": "Runtime", "framework": "Framework", "frontend": "Frontend",
    "backend": "Backend", "storage": "Storage", "orm": "Data access", "migrations": "Migrations",
    "unitTest": "Unit tests", "contractTest": "Contract tests", "integrationTest": "Integration tests",
    "e2eTest": "End-to-end tests", "lint": "Lint", "format": "Format", "typeCheck": "Type check",
    "packageManager": "Package manager", "orchestration": "Orchestration", "observability": "Observability",
}


def default_label(key):
    if key in DEFAULT_LABELS:
        return DEFAULT_LABELS[key]
    words = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", key).replace("_", " ").replace("-", " ")
    return words[:1].upper() + words[1:].lower()


def stack_default_fragments(stack):
    """-> {template: fragment text} generated from the stack profile's `defaults`. The technology
    table is written once, in profile.json, and reaches the constitution annex and AGENTS.md."""
    defaults = stack.get("defaults") or {}
    rows = ["| %s | %s |" % (default_label(k), str(v).replace("|", "\\|").replace("\n", " "))
            for k, v in defaults.items() if v not in (None, "", [])]
    if not rows:
        return {}
    table = ["| Area | Standard |", "|---|---|"] + rows
    label = stack.get("label") or stack["id"]
    return {
        "constitution-template.md": "\n".join([
            "<!-- @slot annexes -->",
            "## Annex T — Technology standards (%s)" % label,
            "",
            "The stack profile sets these standards. A plan that departs from one names the standard and",
            "records the reason in an architecture decision record.",
            ""] + table) + "\n",
        "project/AGENTS.md": "\n".join([
            "<!-- @slot technology -->",
            "### Technology",
            "",
            "The project's standard stack. Do not add a second tool for a row that already has one.",
            ""] + table) + "\n",
    }


def base_checklist_kinds(root):
    base = os.path.join(root, "templates", "checklists")
    return sorted(f[:-len("-template.md")] for f in (os.listdir(base) if os.path.isdir(base) else [])
                  if f.endswith("-template.md"))


def profile_checklist_kinds(profile):
    base = os.path.join(profile["_dir"], "templates", "checklists")
    return sorted(f[:-len("-template.md")] for f in (os.listdir(base) if os.path.isdir(base) else [])
                  if f.endswith("-template.md"))


def checklist_kinds(root, industry):
    """The checklist kinds a project should offer: the industry's list, or every base kind."""
    listed = (industry or {}).get("checklistKinds")
    return list(listed) if listed else base_checklist_kinds(root)


# -------------------------------------------------------------- fragments

def parse_fragment(text, where):
    """-> [(slot, replace, [lines])]. Text before the first slot header is an error."""
    blocks, current = [], None
    for n, line in enumerate(text.split("\n"), 1):
        m = FRAG_RE.match(line)
        if m:
            current = (m.group(1) or m.group(3), bool(m.group(2) or m.group(4)), [])
            blocks.append(current)
        elif current is None:
            if line.strip():
                raise ComposeError("%s:%d: text before the first @slot header" % (where, n))
        else:
            current[2].append(line)
    out = []
    for slot, replace, lines in blocks:
        while lines and not lines[0].strip():
            lines.pop(0)
        while lines and not lines[-1].strip():
            lines.pop()
        if not lines:
            raise ComposeError('%s: slot "%s" is empty' % (where, slot))
        out.append((slot, replace, lines))
    return out


def base_slots(text, where):
    """-> {slot: "point" | "block"}; checks the markers are well formed."""
    slots, open_block = {}, None
    for n, line in enumerate(text.split("\n"), 1):
        m = SLOT_RE.match(line)
        if not m:
            if "slot:" in line and re.match(r"^\s*(<!--|#)\s*@?slot:", line):
                raise ComposeError("%s:%d: malformed slot marker: %s" % (where, n, line.strip()))
            continue
        name, edge = (m.group(1) or m.group(3)), (m.group(2) or m.group(4))
        if edge == ":begin":
            if open_block:
                raise ComposeError('%s:%d: slot "%s" opens inside "%s"' % (where, n, name, open_block))
            if name in slots:
                raise ComposeError('%s:%d: slot "%s" appears twice' % (where, n, name))
            open_block, slots[name] = name, "block"
        elif edge == ":end":
            if open_block != name:
                raise ComposeError('%s:%d: ":end" for "%s" has no matching ":begin"' % (where, n, name))
            open_block = None
        else:
            if open_block:
                raise ComposeError('%s:%d: point slot "%s" inside block "%s"' % (where, n, name, open_block))
            if name in slots:
                raise ComposeError('%s:%d: slot "%s" appears twice' % (where, n, name))
            slots[name] = "point"
    if open_block:
        raise ComposeError('%s: block slot "%s" is never closed' % (where, open_block))
    return slots


def compose_text(base_text, layers, where):
    """layers: [(layer name, fragment text)] in order. -> (composed text, overlaid?)"""
    slots = base_slots(base_text, where)
    appends, replaces = {}, {}
    for layer, text in layers:
        for slot, replace, lines in parse_fragment(text, "%s [%s]" % (where, layer)):
            if slot not in slots:
                raise ComposeError('%s [%s]: slot "%s" is not in the base template (has: %s)'
                                   % (where, layer, slot, ", ".join(sorted(slots)) or "none"))
            if slots[slot] == "block" and not replace:
                raise ComposeError('%s [%s]: "%s" is a block slot; write "@slot %s replace"' % (where, layer, slot, slot))
            if slots[slot] == "point" and replace:
                raise ComposeError('%s [%s]: "%s" is a point slot; it takes appends, not replace' % (where, layer, slot))
            if replace:
                # The project-local layer may override a profile. Two profiles may not fight.
                if slot in replaces and layer != "project":
                    raise ComposeError('%s: slot "%s" is replaced by both "%s" and "%s"' % (where, slot, replaces[slot][0], layer))
                replaces[slot] = (layer, lines)
            else:
                appends.setdefault(slot, []).append(lines)

    out, skipping = [], None
    for line in base_text.split("\n"):
        m = SLOT_RE.match(line)
        if not m:
            if skipping is None:
                out.append(line)
            continue
        name, edge = (m.group(1) or m.group(3)), (m.group(2) or m.group(4))
        if edge == ":begin":
            if name in replaces:
                out.extend(replaces[name][1])
                skipping = name
        elif edge == ":end":
            skipping = None
        else:
            tight = name.endswith(TIGHT_SUFFIXES)
            for lines in appends.get(name, []):
                out.extend(lines)
                if not tight:
                    out.append("")
    # A slot at the end of a file would otherwise leave two newlines there.
    return "\n".join(out).rstrip("\n") + "\n", bool(appends or replaces)


# ----------------------------------------------------------------- header

def is_markdown(rel):
    return rel.endswith(".md")


def header_line(rel, ctx):
    body = ("sdd-speckit:composed industry=%s stack=%s inputs=%s — regenerate with the onboard phase; do not edit"
            % (ctx["industry"], ctx["stack"], ctx["inputs"]))
    return "<!-- %s -->" % body if is_markdown(rel) else "# %s" % body


def with_header(rel, text, ctx):
    head = header_line(rel, ctx)
    if text.startswith("---\n"):  # YAML frontmatter must stay first
        end = text.find("\n---\n", 4)
        if end != -1:
            return text[:end + 5] + head + "\n" + text[end + 5:]
    return head + "\n" + text


def is_composed(text):
    return bool(COMPOSED_RE.search("\n".join(text.split("\n")[:12])))


def merge_block(existing, block):
    """Replaces the marked block in an existing file, or appends it. Other text is kept."""
    if not existing:
        return block
    start, end = existing.find(BLOCK_BEGIN), existing.find(BLOCK_END)
    if start != -1 and end > start:
        after = existing[end + len(BLOCK_END):]
        if after.startswith("\n"):
            after = after[1:]
        return existing[:start] + block + after
    return existing.rstrip("\n") + "\n\n" + block


# ------------------------------------------------------------------- plan

def plan(root, project, industry_id, stack_id, targets):
    """-> (ctx, [artifact]) where artifact = {output, content, policy, source}. Reads only."""
    industry = load_profile(root, "industry", industry_id)
    stack = load_profile(root, "stack", stack_id)
    layer_dirs = []
    if industry:
        layer_dirs.append(("industry:%s" % industry["id"], os.path.join(industry["_dir"], "fragments")))
    if stack:
        layer_dirs.append(("stack:%s" % stack["id"], os.path.join(stack["_dir"], "fragments")))
    if project:
        layer_dirs.append(("project", os.path.join(project, LOCAL_FRAGMENTS)))

    templates_dir = os.path.join(root, "templates")
    base_files = [f for f in walk(templates_dir) if f != "manifest.json"]
    manifest = read_json(os.path.join(templates_dir, "manifest.json"), {}) or {}
    project_entries = {e["template"]: e for e in manifest.get("project", [])}

    # Whole-file templates a profile adds. They may not shadow a base template.
    extra = {}
    for profile in (industry, stack):
        if not profile:
            continue
        tdir = os.path.join(profile["_dir"], "templates")
        for rel in walk(tdir) if os.path.isdir(tdir) else []:
            if rel in base_files or rel in extra:
                raise ComposeError('profile "%s" ships templates/%s, which already exists' % (profile["id"], rel))
            extra[rel] = os.path.join(tdir, rel)

    fragments = {}  # rel -> [(layer, text)]
    for layer, fdir in layer_dirs:
        for rel in walk(fdir) if os.path.isdir(fdir) else []:
            if rel not in base_files and rel not in extra:
                raise ComposeError("%s: fragments/%s matches no template" % (layer, rel))
            fragments.setdefault(rel, []).append((layer, read(os.path.join(fdir, rel))))
        if stack and layer == "stack:%s" % stack["id"]:
            # Generated from profile.json, after the stack's own fragments and before the project's.
            for rel, text in sorted(stack_default_fragments(stack).items()):
                fragments.setdefault(rel, []).append(("%s:defaults" % layer, text))

    digest = hashlib.sha256()
    sources = {}
    for rel in sorted(set(base_files) | set(extra)):
        sources[rel] = read(extra[rel] if rel in extra else os.path.join(templates_dir, rel))
        digest.update(rel.encode() + b"\0" + sources[rel].encode() + b"\0")
        for layer, text in fragments.get(rel, []):
            digest.update(layer.encode() + b"\0" + text.encode() + b"\0")

    ctx = {
        "industry": industry["id"] if industry else NONE_IDS["industry"],
        "stack": stack["id"] if stack else NONE_IDS["stack"],
        "inputs": digest.hexdigest()[:12],
        "checklistKinds": checklist_kinds(root, industry),
    }

    artifacts = []
    for rel in sorted(sources):
        text, overlaid = compose_text(sources[rel], fragments.get(rel, []), rel)
        if rel.startswith("project/"):
            entry = project_entries.get(rel)
            if not entry:
                raise ComposeError("templates/%s has no entry in templates/manifest.json" % rel)
            want = (entry.get("when") or {}).get("target")
            if want and want not in targets:
                continue
            policy = entry.get("ifExists", "skip")
            body = with_header(rel, text, ctx)
            if policy == "merge-block":
                body = "%s\n%s\n%s\n" % (BLOCK_BEGIN, body.rstrip("\n"), BLOCK_END)
            artifacts.append({"output": entry["output"], "content": body, "policy": policy, "source": rel})
        elif overlaid or rel in extra:
            # An untouched base template is not copied: it keeps resolving from the framework,
            # so a framework upgrade still reaches it.
            artifacts.append({"output": "%s/%s" % (OVERRIDES, rel), "content": with_header(rel, text, ctx),
                              "policy": "replace-if-composed", "source": rel})
    return ctx, artifacts


def resolve(project, art, force):
    """-> (action, final content or None). Actions: write, unchanged, skip-exists, skip-edited."""
    path = os.path.join(project, art["output"])
    existing = read(path) if os.path.isfile(path) else None
    policy = art["policy"]
    if policy == "merge-block":
        final = merge_block(existing, art["content"])
    elif existing is None:
        final = art["content"]
    elif policy == "skip":
        return "skip-exists", None
    elif policy == "replace-if-composed" and not is_composed(existing) and not force:
        return "skip-edited", None
    else:
        final = art["content"]
    return ("unchanged" if final == existing else "write"), final


def stale_overrides(project, artifacts):
    """Composed files in the overrides directory that this composition no longer produces."""
    base = os.path.join(project, OVERRIDES)
    keep = {a["output"] for a in artifacts}
    out = []
    for rel in walk(base) if os.path.isdir(base) else []:
        output = "%s/%s" % (OVERRIDES, rel)
        if output not in keep and is_composed(read(os.path.join(base, rel))):
            out.append(output)
    return out


def run(project, industry, stack, targets, dry_run=False, force=False, check=False, root=ROOT):
    ctx, artifacts = plan(root, project, industry, stack, targets)
    actions = []
    for art in artifacts:
        action, final = resolve(project, art, force)
        if action == "write" and not (dry_run or check):
            path = os.path.join(project, art["output"])
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(final)
        actions.append({"path": art["output"], "action": action, "source": art["source"]})
    for output in stale_overrides(project, artifacts):
        if not (dry_run or check):
            os.remove(os.path.join(project, output))
        actions.append({"path": output, "action": "remove", "source": None})
    return ctx, actions


# ------------------------------------------------------------------- lint

ID_CELL = re.compile(r"^\| ([A-Z]{1,4}(?:-[A-Z]{2,4})?-?\d{1,3}) \|")


def table_cells(line):
    stripped = re.sub(r"`[^`]*`", "`", line).replace("\\|", "")
    return stripped.count("|") - 1


def lint_composed(rel, text, problems, combo):
    lines = text.split("\n")
    if any(SLOT_RE.match(l) or FRAG_RE.match(l) for l in lines):
        problems.append("%s %s: a slot marker survived composition" % (combo, rel))
    seen, width, in_code = {}, None, False
    for n, line in enumerate(lines, 1):
        if line.startswith("```"):
            in_code = not in_code
        if in_code or not line.startswith("|"):
            width = None
            continue
        cells = table_cells(line)
        if width is None:
            width = cells
        elif cells != width:
            problems.append("%s %s:%d: table row has %d cells, the header has %d" % (combo, rel, n, cells, width))
        m = ID_CELL.match(line)
        if m:
            if m.group(1) in seen:
                problems.append("%s %s:%d: id %s repeats line %d" % (combo, rel, n, m.group(1), seen[m.group(1)]))
            seen[m.group(1)] = n


def lint(root=ROOT):
    problems = []
    templates_dir = os.path.join(root, "templates")
    for rel in walk(templates_dir):
        if rel == "manifest.json":
            continue
        try:
            base_slots(read(os.path.join(templates_dir, rel)), "templates/" + rel)
        except ComposeError as err:
            problems.append(str(err))

    manifest = read_json(os.path.join(templates_dir, "manifest.json"))
    if manifest is None:
        problems.append("templates/manifest.json is missing or is not JSON")
    else:
        for entry in manifest.get("project", []):
            if not os.path.isfile(os.path.join(templates_dir, entry.get("template", ""))):
                problems.append("manifest.json: template %s does not exist" % entry.get("template"))
            if entry.get("ifExists") not in ("merge-block", "replace-if-composed", "skip"):
                problems.append("manifest.json: %s has an unknown ifExists" % entry.get("template"))
            if not entry.get("output"):
                problems.append("manifest.json: %s has no output" % entry.get("template"))

    catalog = read_json(os.path.join(root, "mcp", "catalog.json"), {}) or {}
    connectors = {c.get("id") for c in catalog.get("connectors", [])}
    have_catalog = bool(connectors)
    for kind in ("industry", "stack"):
        for pid in list_profiles(root, kind):
            where = "profiles/%s/%s" % ("industries" if kind == "industry" else "stacks", pid)
            prof = read_json(os.path.join(profile_dir(root, kind, pid), "profile.json"))
            if not isinstance(prof, dict):
                problems.append("%s/profile.json is not a JSON object" % where)
                continue
            for key in ("schema", "kind", "id", "label", "description"):
                if not prof.get(key):
                    problems.append("%s/profile.json: %s is required" % (where, key))
            if prof.get("kind") != kind:
                problems.append('%s/profile.json: kind must be "%s"' % (where, kind))
            if prof.get("id") != pid:
                problems.append("%s/profile.json: id must equal the directory name" % where)
            for std in prof.get("standards", []):
                for key in ("id", "title", "reviewedOn"):
                    if not std.get(key):
                        problems.append("%s/profile.json: a standards entry has no %s" % (where, key))
            for pat in (prof.get("harness") or {}).get("sensitivePatterns", []):
                try:
                    re.compile(pat.get("regex", ""))
                except re.error as err:
                    problems.append("%s/profile.json: sensitivePatterns %s: %s" % (where, pat.get("id"), err))
            prof["_dir"] = profile_dir(root, kind, pid)
            own = profile_checklist_kinds(prof)
            known = set(base_checklist_kinds(root)) | set(own)
            for ck in prof.get("checklistKinds", []):
                if ck not in known:
                    problems.append('%s/profile.json: checklistKinds "%s" has no checklists/%s-template.md' % (where, ck, ck))
            if "checklistKinds" in prof:
                for ck in own:
                    if ck not in prof["checklistKinds"]:
                        problems.append('%s/profile.json: checklistKinds does not list its own "%s"' % (where, ck))
            for cid in prof.get("recommendedMcp", []):
                if have_catalog and cid not in connectors:
                    problems.append('%s/profile.json: recommendedMcp "%s" is not in mcp/catalog.json' % (where, cid))
            if not isinstance(prof.get("defaults", {}), dict):
                problems.append("%s/profile.json: defaults must be an object" % where)
            fdir = os.path.join(profile_dir(root, kind, pid), "fragments")
            for rel in walk(fdir) if os.path.isdir(fdir) else []:
                text = read(os.path.join(fdir, rel))
                for bad in FORBIDDEN_IN_FRAGMENTS:
                    if bad.search(text):
                        problems.append("%s/fragments/%s: contains %s; a fragment must be assistant-neutral" % (where, rel, bad.pattern))
                if kind == "stack":
                    if rel in STACK_MAY_NOT_OVERLAY:
                        problems.append("%s/fragments/%s: a stack may not overlay this template (it stays technology-free)" % (where, rel))
                    try:
                        for slot, _, _ in parse_fragment(text, rel):
                            if slot in STACK_MAY_NOT_FILL.get(rel, ()):
                                problems.append('%s/fragments/%s: a stack may not fill slot "%s"' % (where, rel, slot))
                    except ComposeError as err:
                        problems.append("%s: %s" % (where, err))

    industries = [NONE_IDS["industry"]] + list_profiles(root, "industry")
    stacks = [NONE_IDS["stack"]] + list_profiles(root, "stack")
    for industry, stack in itertools.product(industries, stacks):
        combo = "[%s + %s]" % (industry, stack)
        try:
            _, artifacts = plan(root, None, industry, stack, ["claude", "copilot"])
        except ComposeError as err:
            problems.append("%s %s" % (combo, err))
            continue
        for art in artifacts:
            lint_composed(art["source"], art["content"], problems, combo)
    return problems, len(industries) * len(stacks)


# -------------------------------------------------------------------- cli

def main(argv=None):
    ap = argparse.ArgumentParser(description="Compose sdd-speckit templates from base, industry and stack layers.")
    ap.add_argument("--project")
    ap.add_argument("--industry")
    ap.add_argument("--stack")
    ap.add_argument("--targets")
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--force", action="store_true", help="replace a composed file even after a hand edit")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--lint", action="store_true")
    ap.add_argument("--list", action="store_true")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)

    if args.list:
        out = {kind: [{k: v for k, v in load_profile(ROOT, kind, pid).items() if not k.startswith("_")}
                      for pid in list_profiles(ROOT, kind)] for kind in ("industry", "stack")}
        print(json.dumps(out, indent=2))
        return 0

    if args.lint:
        problems, combos = lint()
        if args.json:
            print(json.dumps({"ok": not problems, "combinations": combos, "problems": problems}, indent=2))
        elif problems:
            print("Template lint failed (%d):" % len(problems), file=sys.stderr)
            for p in problems:
                print("  " + p, file=sys.stderr)
        else:
            print("Templates and profiles are clean (%d industry x stack combinations composed)." % combos)
        return 1 if problems else 0

    if not args.project:
        ap.error("--project is required unless --lint or --list is given")
    project = os.path.abspath(args.project)
    record = read_json(os.path.join(project, CONFIG), {}) or {}
    industry = args.industry or record.get("industry") or NONE_IDS["industry"]
    stack = args.stack or record.get("stack") or NONE_IDS["stack"]
    targets = (args.targets.split(",") if args.targets
               else (record.get("assistant") or {}).get("targets") or ["claude"])

    try:
        ctx, actions = run(project, industry, stack, targets, dry_run=args.dry_run, force=args.force, check=args.check)
    except ComposeError as err:
        if args.json:
            print(json.dumps({"ok": False, "error": str(err)}))
        else:
            print("compose-templates: %s" % err, file=sys.stderr)
        return 2

    stale = [a for a in actions if a["action"] in ("write", "remove")]
    if args.json:
        print(json.dumps({"ok": not (args.check and stale), "context": ctx, "dryRun": args.dry_run,
                          "check": args.check, "actions": actions}, indent=2))
    elif args.check:
        if stale:
            print("Composed templates are stale (industry=%s, stack=%s):" % (ctx["industry"], ctx["stack"]), file=sys.stderr)
            for a in stale:
                print("  %-7s %s" % ("extra" if a["action"] == "remove" else "changed", a["path"]), file=sys.stderr)
            print("Regenerate: python3 %s --project ." % os.path.relpath(os.path.abspath(__file__), project), file=sys.stderr)
        else:
            print("Composed templates are current (industry=%s, stack=%s)." % (ctx["industry"], ctx["stack"]))
    else:
        verb = {"write": "would write" if args.dry_run else "wrote", "unchanged": "unchanged",
                "remove": "would remove" if args.dry_run else "removed",
                "skip-exists": "kept (already exists)", "skip-edited": "kept (edited by hand; --force replaces it)"}
        print("Composed with industry=%s, stack=%s" % (ctx["industry"], ctx["stack"]))
        for a in actions:
            print("  %s: %s" % (verb[a["action"]], a["path"]))
        if not actions:
            print("  nothing to compose: no profile overlays any template")
    return 1 if (args.check and stale) else 0


if __name__ == "__main__":
    sys.exit(main())
